1	//! This is a low-level set of contracts implementing different proxy patterns
2	//! with and without upgradeability.
3	use alloc::vec::Vec;
4	
5	use alloy_primitives::Address;
6	use stylus_sdk::{
7	    call, host::VM, prelude::*, stylus_core::calls::errors::Error,
8	};
9	
10	pub mod beacon;
11	pub mod erc1967;
12	pub mod utils;
