14	/// This trait provides a fallback function that delegates all calls to another
15	/// contract using the Stylus [`delegate_call`] function. We refer to the second
16	/// contract as the _implementation_ behind the proxy, and it has to be
17	/// specified by overriding the virtual [`IProxy::implementation`] function.
18	///
19	/// Additionally, delegation to the implementation can be triggered manually
20	/// through the [`IProxy::do_fallback`] function, or to a different contract
21	/// through the [`IProxy::delegate`] function.
22	///
23	/// The success and return data of the delegated call will be returned back
24	/// to the caller of the proxy.
25	///
26	/// The proxy reaches the host environment through [`HostAccess::vm`], so
27	/// implementors have to be [`HostAccess`] with the [`VM`] as their host, like
28	/// every `#[storage]` type is.
29	///
30	/// # Safety
31	///
32	/// This trait is unsafe to implement because it uses the `unsafe`
33	/// [`delegate_call`] function.
34	///
35	/// The caller must ensure that `self` is a valid contract storage context.
36	///
37	/// The caller must ensure that the implementation contract is a valid contract
38	/// address.
39	pub unsafe trait IProxy:
40	    TopLevelStorage + HostAccess<Host = VM> + Sized
41	{
42	    /// Delegates the current call to [`IProxy::implementation`].
43	    ///
44	    /// This function does not return to its internal call site, it will
45	    /// return directly to the external caller.
46	    ///
47	    /// # Arguments
48	    ///
49	    /// * `&mut self` - Write access to the contract's state.
50	    /// * `implementation` - The address of the implementation contract.
51	    /// * `calldata` - The calldata to delegate to the implementation contract.
52	    ///
53	    /// # Errors
54	    ///
55	    /// Returns a [`stylus_sdk::stylus_core::calls::errors::Error`] if the
56	    /// delegate call fails. This error may represent:
57	    /// * A revert from the implementation contract, containing the revert data.
58	    /// * Failure to decode the return data from the implementation contract.
59	    /// * Other low-level call failures as defined by the Stylus SDK.
60	    #[allow(clippy::missing_safety_doc)]
61	    unsafe fn delegate(
62	        &mut self,
63	        implementation: Address,
64	        calldata: &[u8],
65	    ) -> Result<Vec<u8>, Error> {
66	        // `Call::new_mutating` only needs `self` to prove exclusive access to
67	        // the top-level storage. Its borrow ends right away, which lets
68	        // `self.vm()` be borrowed for the call itself.
69	        let call = Call::new_mutating(self);
70	        call::delegate_call(self.vm(), call, implementation, calldata)
71	    }
72	
73	    /// This is a virtual function that should be overridden so it
74	    /// returns the address to which the fallback function and
75	    /// [`IProxy::do_fallback`] should delegate.
76	    ///
77	    /// # Arguments
78	    ///
79	    /// * `&self` - Read access to the contract's state.
80	    ///
81	    /// # Errors
82	    ///
83	    /// Implementing contracts should define their own error types for this
84	    /// function. Typically, errors may include:
85	    /// * The implementation address is invalid (e.g., not a contract).
86	    /// * The implementation is not a contract.
87	    ///
88	    /// The error should be encoded as a `Vec<u8>`.
89	    fn implementation(&self) -> Result<Address, Vec<u8>>;
90	
91	    /// Fallback function that delegates calls to the address returned
92	    /// by [`IProxy::implementation`]. Will run if no other function in the
93	    /// contract matches the call data.
94	    ///
95	    /// # Arguments
96	    ///
97	    /// * `&mut self` - Write access to the contract's state.
98	    /// * `calldata` - The calldata to delegate to the implementation contract.
99	    ///
100	    /// # Errors
101	    ///
102	    /// Implementing contracts should define their own error types for this
103	    /// function. Typically, errors may include:
104	    /// * The implementation address is invalid (e.g., not a contract).
105	    /// * The implementation is not a contract.
106	    /// * The implementation reverted with a reason.
107	    ///
108	    /// The error should be encoded as a `Vec<u8>`.
109	    #[allow(clippy::missing_safety_doc)]
110	    unsafe fn do_fallback(
111	        &mut self,
112	        calldata: &[u8],
113	    ) -> Result<Vec<u8>, Vec<u8>> {
114	        Ok(self.delegate(self.implementation()?, calldata)?)
115	    }
116	}
