118	// The unit tests of the proxies are not built with the `export-abi` feature.
119	// For the ABI export, `#[public]` defines items at the level of the module
120	// (like `print_from_args`), that collide as soon as a module defines several
121	// contracts, as the tests of the proxies do. They have no use for the export.
122	
123	/// Helpers shared by the unit tests of the proxies.
124	///
125	/// [`TestVM`](stylus_sdk::testing::TestVM) holds the state of a single contract
126	/// and doesn't run the contracts a call is made to: the outcome of such a call
127	/// is whatever has been mocked for it. The helpers run those contracts, so that
128	/// their outcome can be mocked.
129	#[cfg(all(test, not(feature = "export-abi")))]
130	mod test_helpers {
131	    use core::{borrow::BorrowMut, fmt::Debug};
132	
133	    use alloy_primitives::Address;
134	    use alloy_sol_types::SolEvent;
135	    use stylus_sdk::{
136	        abi::{router_entrypoint, Router},
137	        host::VM,
138	        prelude::*,
139	        testing::TestVM,
140	        ArbResult,
141	    };
142	
143	    /// Gives some code to `account`, so that `vm` sees a contract there.
144	    pub(crate) fn deploy(vm: &TestVM, account: Address) {
145	        vm.set_code(account, vec![0x60, 0x00]);
146	    }
147	
148	    /// Runs `calldata` on the contract `C` over the state held by `vm`, the
149	    /// way the contract's entrypoint does.
150	    ///
151	    /// A delegate call runs the code of the callee over the storage of the
152	    /// caller, so the outcome of a delegate call is the one of running the
153	    /// callee over the state of the caller's `vm`. The state changes and the
154	    /// logs of the callee end up in `vm` as well.
155	    pub(crate) fn execute<C>(vm: &TestVM, calldata: &[u8]) -> ArbResult
156	    where
157	        C: Router<C>
158	            + StorageType
159	            + TopLevelStorage
160	            + ValueDenier
161	            + BorrowMut<<C as Router<C>>::Storage>,
162	    {
163	        router_entrypoint::<C, C>(
164	            calldata.to_vec(),
165	            VM { host: Box::new(vm.clone()) },
166	        )
167	    }
168	
169	    /// Asserts that `event` was emitted at least once.
170	    #[track_caller]
171	    pub(crate) fn assert_emitted<E: SolEvent + Debug>(vm: &TestVM, event: &E) {
172	        let log = event.encode_log_data();
173	        let expected = (log.topics().to_vec(), log.data.to_vec());
174	        let emitted = vm.get_emitted_logs();
175	        assert!(
176	            emitted.contains(&expected),
177	            "event was not emitted: {event:?}, emitted logs: {emitted:?}"
178	        );
179	    }
180	}
