216	    #[public]
217	    impl ProxyExample {
218	        #[constructor]
219	        fn constructor(&mut self, implementation: Address) {
220	            self.implementation.set(implementation);
221	        }
222	
223	        fn set_error_on_implementation(
224	            &mut self,
225	            error_on_implementation: bool,
226	        ) {
227	            self.error_on_implementation.set(error_on_implementation);
228	        }
229	
230	        fn implementation(&self) -> Result<Address, Vec<u8>> {
231	            if self.error_on_implementation.get() {
232	                return Err("implementation error".abi_encode());
233	            }
234	            Ok(self.implementation.get())
235	        }
236	
237	        #[fallback]
238	        fn fallback(&mut self, calldata: &[u8]) -> ArbResult {
239	            unsafe { self.do_fallback(calldata) }
240	        }
241	    }
