310	    sol! {
311	        interface IERC20 {
312	            function balanceOf(address account) external view returns (uint256);
313	            function totalSupply() external view returns (uint256);
314	            function mint(address to, uint256 value) external;
315	            function transfer(address to, uint256 value) external returns (bool);
316	        }
