319	    /// Calls the proxy with `calldata`.
320	    ///
321	    /// The proxy delegates the call to [`ERC20`], so the call is mocked with
322	    /// the outcome of running [`Erc20Example`] over the storage of the proxy.
323	    fn call_proxy(
324	        vm: &TestVM,
325	        proxy: &mut ProxyExample,
326	        calldata: &[u8],
327	    ) -> ArbResult {
328	        vm.mock_delegate_call(
329	            ERC20,
330	            calldata.to_vec(),
331	            execute::<Erc20Example>(vm, calldata),
332	        );
333	        proxy.fallback(calldata)
334	    }
