336	    #[test]
337	    fn constructs() {
338	        let vm = TestVM::default();
339	        let mut proxy = ProxyExample::from(&vm);
340	        vm.set_sender(ALICE);
341	
342	        proxy.constructor(ERC20);
343	
344	        let implementation = proxy
345	            .implementation()
346	            .expect("should be able to get implementation");
347	        assert_eq!(implementation, ERC20);
348	    }
