350	    #[test]
351	    fn delegate() {
352	        let vm = TestVM::default();
353	        let mut proxy = ProxyExample::from(&vm);
354	        vm.set_sender(ALICE);
355	
356	        proxy.constructor(ERC20);
357	
358	        // verify initial balance is [`U256::ZERO`].
359	        let balance_of_alice_call =
360	            IERC20::balanceOfCall { account: ALICE }.abi_encode();
361	        let balance = call_proxy(&vm, &mut proxy, &balance_of_alice_call)
362	            .expect("should be able to get balance");
363	        assert_eq!(balance, U256::ZERO.abi_encode());
364	
365	        let total_supply_call = IERC20::totalSupplyCall {}.abi_encode();
366	        let total_supply = call_proxy(&vm, &mut proxy, &total_supply_call)
367	            .expect("should be able to get total supply");
368	        assert_eq!(total_supply, U256::ZERO.abi_encode());
369	
370	        // mint 1000 tokens.
371	        let amount = U256::from(1000);
372	
373	        let mint_call =
374	            IERC20::mintCall { to: ALICE, value: amount }.abi_encode();
375	        call_proxy(&vm, &mut proxy, &mint_call)
376	            .expect("should be able to mint");
377	        // the implementation runs in the context of the proxy, so the proxy is
378	        // the one that emits the event.
379	        assert_emitted(
380	            &vm,
381	            &erc20::Transfer { from: Address::ZERO, to: ALICE, value: amount },
382	        );
383	
384	        // check that the balance can be accurately fetched through the proxy.
385	        let balance = call_proxy(&vm, &mut proxy, &balance_of_alice_call)
386	            .expect("should be able to get balance");
387	        assert_eq!(balance, amount.abi_encode());
388	
389	        let total_supply = call_proxy(&vm, &mut proxy, &total_supply_call)
390	            .expect("should be able to get total supply");
391	        assert_eq!(total_supply, amount.abi_encode());
392	
393	        // check that the balance can be transferred through the proxy.
394	        let transfer_call =
395	            IERC20::transferCall { to: BOB, value: amount }.abi_encode();
396	        call_proxy(&vm, &mut proxy, &transfer_call)
397	            .expect("should be able to transfer");
398	
399	        assert_emitted(
400	            &vm,
401	            &erc20::Transfer { from: ALICE, to: BOB, value: amount },
402	        );
403	
404	        let balance = call_proxy(&vm, &mut proxy, &balance_of_alice_call)
405	            .expect("should be able to get balance");
406	        assert_eq!(balance, U256::ZERO.abi_encode());
407	
408	        let balance_of_bob_call =
409	            IERC20::balanceOfCall { account: BOB }.abi_encode();
410	        let balance = call_proxy(&vm, &mut proxy, &balance_of_bob_call)
411	            .expect("should be able to get balance");
412	        assert_eq!(balance, amount.abi_encode());
413	
414	        let total_supply = call_proxy(&vm, &mut proxy, &total_supply_call)
415	            .expect("should be able to get total supply");
416	        assert_eq!(total_supply, amount.abi_encode());
417	    }
