419	    #[test]
420	    fn delegate_returns_error() {
421	        let vm = TestVM::default();
422	        let mut proxy = ProxyExample::from(&vm);
423	        vm.set_sender(ALICE);
424	
425	        proxy.constructor(ERC20);
426	
427	        let amount = U256::from(1000);
428	        let transfer_call =
429	            IERC20::transferCall { to: BOB, value: amount }.abi_encode();
430	        let err = call_proxy(&vm, &mut proxy, &transfer_call)
431	            .expect_err("should revert on transfer");
432	
433	        assert_eq!(
434	            err,
435	            erc20::ERC20InsufficientBalance {
436	                sender: ALICE,
437	                balance: U256::ZERO,
438	                needed: amount,
439	            }
440	            .abi_encode()
441	        );
442	    }
