444	    #[test]
445	    fn direct_delegate_to_different_implementation() {
446	        let vm = TestVM::default();
447	        let mut proxy = ProxyExample::from(&vm);
448	        vm.set_sender(ALICE);
449	
450	        proxy.constructor(ERC20);
451	
452	        // mint tokens. The second implementation runs over the storage of the
453	        // proxy, so this is where its balances have to be.
454	        let amount = U256::from(500);
455	        Erc20Example::from(&vm)
456	            .mint(ALICE, amount)
457	            .expect("should be able to mint");
458	
459	        // use direct delegate to call the second contract. Delegating to the
460	        // implementation the proxy is configured with would fail.
461	        let balance_of_call =
462	            IERC20::balanceOfCall { account: ALICE }.abi_encode();
463	        vm.mock_delegate_call(
464	            ERC20,
465	            balance_of_call.clone(),
466	            Err("wrong implementation".abi_encode()),
467	        );
468	        vm.mock_delegate_call(
469	            ERC20_2,
470	            balance_of_call.clone(),
471	            execute::<Erc20Example>(&vm, &balance_of_call),
472	        );
473	        let balance = unsafe {
474	            proxy.delegate(ERC20_2, &balance_of_call).expect(
475	                "should be able to delegate to different implementation",
476	            )
477	        };
478	        assert_eq!(balance, amount.abi_encode());
479	    }
