481	    #[test]
482	    fn fallback_reverts_on_implementation_error() {
483	        let vm = TestVM::default();
484	        let mut proxy = ProxyExample::from(&vm);
485	        vm.set_sender(ALICE);
486	
487	        // create proxy with [`Address::ZERO`] as implementation (invalid).
488	        proxy.set_error_on_implementation(true);
489	
490	        let balance_of_call =
491	            IERC20::balanceOfCall { account: ALICE }.abi_encode();
492	        let err = proxy
493	            .fallback(&balance_of_call)
494	            .expect_err("should fail when implementation is zero address");
495	
496	        assert_eq!(err, "implementation error".abi_encode());
497	    }
498	}
