1	//! This contract implements an upgradeable proxy. It is upgradeable because
2	//! calls are delegated to an implementation address that can be changed. This
3	//! address is stored in storage in the location specified by
4	//! [ERC-1967], so that it doesn't conflict with the storage layout of the
5	//! implementation behind the proxy.
6	//!
7	//! [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
8	use alloc::{vec, vec::Vec};
9	
10	use alloy_primitives::Address;
11	use stylus_sdk::{abi::Bytes, prelude::*};
12	
13	use crate::proxy::IProxy;
14	
15	pub mod utils;
16	
17	pub use sol::*;
18	pub use utils::{Erc1967Utils, Error};
19	
20	#[cfg_attr(coverage_nightly, coverage(off))]
21	mod sol {
22	    use alloy_sol_macro::sol;
23	
24	    sol! {
25	        /// Emitted when the implementation is upgraded.
26	        #[derive(Debug)]
27	        #[allow(missing_docs)]
28	        event Upgraded(address indexed implementation);
29	
30	        /// Emitted when the admin account has changed.
31	        #[derive(Debug)]
32	        #[allow(missing_docs)]
33	        event AdminChanged(address previous_admin, address new_admin);
34	
35	        /// Emitted when the beacon is changed.
36	        #[derive(Debug)]
37	        #[allow(missing_docs)]
38	        event BeaconUpgraded(address indexed beacon);
39	    }
40	}
41	
42	/// State of an [`Erc1967Proxy`] token.
43	#[storage]
44	pub struct Erc1967Proxy;
45	
46	/// NOTE: Implementation of [`TopLevelStorage`] to be able use `&mut self` when
47	/// calling other contracts and not `&mut (impl TopLevelStorage +
48	/// BorrowMut<Self>)`. Should be fixed in the future by the Stylus team.
49	unsafe impl TopLevelStorage for Erc1967Proxy {}
50	
51	impl Erc1967Proxy {
52	    /// Initializes the upgradeable proxy with an initial implementation
53	    /// specified by `implementation`.
54	    ///
55	    /// If `data` is nonempty, it's used as data in a delegate call to
56	    /// `implementation`. This will typically be an encoded function call,
57	    /// and allows initializing the storage of the proxy like a Solidity
58	    /// constructor.
59	    ///
60	    /// # Arguments
61	    ///
62	    /// * `&mut self` - Write access to the contract's state.
63	    /// * `implementation` - Address of the implementation contract.
64	    /// * `data` - Data to pass to the implementation contract.
65	    ///
66	    /// # Errors
67	    ///
68	    /// * [`Error::InvalidImplementation`] - If the implementation is not a
69	    ///   valid implementation.
70	    /// * [`Error::NonPayable`] - If `data` is empty and `self.vm().msg_value()`
71	    ///   is not [`U256::ZERO`][U256].
72	    /// * [`Error::FailedCall`] - If the call to the implementation fails.
73	    /// * [`Error::FailedCallWithReason`] - If the call to the implementation
74	    ///   fails with a revert reason.
75	    ///
76	    /// [U256]: alloy_primitives::U256
77	    pub fn constructor(
78	        &mut self,
79	        implementation: Address,
80	        data: &Bytes,
81	    ) -> Result<(), Error> {
82	        Erc1967Utils::upgrade_to_and_call(self, implementation, data)
83	    }
84	}
85	
86	unsafe impl IProxy for Erc1967Proxy {
87	    fn implementation(&self) -> Result<Address, Vec<u8>> {
88	        Ok(Erc1967Utils::get_implementation(self))
89	    }
90	}
