1	//! This contract implements a proxy that gets the implementation address for
2	//! each call from an [`UpgradeableBeacon`][UpgradeableBeacon].
3	//!
4	//! The beacon address can only be set once during construction, and cannot be
5	//! changed afterwards. It is stored in an immutable variable to avoid
6	//! unnecessary storage reads, and also in the beacon storage slot specified by
7	//! [ERC-1967] so that it can be accessed externally.
8	//!
9	//! CAUTION: Since the beacon address can never be changed, you must ensure that
10	//! you either control the beacon, or trust the beacon to not upgrade the
11	//! implementation maliciously.
12	//!
13	//! IMPORTANT: Do not use the implementation logic to modify the beacon storage
14	//! slot. Doing so would leave the proxy in an inconsistent state where the
15	//! beacon storage slot does not match the beacon address.
16	//!
17	//! [UpgradeableBeacon]: super::UpgradeableBeacon
18	//! [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
19	
20	use alloc::{vec, vec::Vec};
21	
22	use alloy_primitives::Address;
23	use stylus_sdk::{abi::Bytes, prelude::*, storage::StorageAddress};
24	
25	use crate::proxy::{
26	    beacon::IBeaconInterface,
27	    erc1967::{Erc1967Utils, Error},
28	    IProxy,
29	};
30	
31	/// State of an [`BeaconProxy`] contract.
32	#[storage]
33	pub struct BeaconProxy {
34	    beacon: StorageAddress,
35	}
36	
37	/// NOTE: Implementation of [`TopLevelStorage`] to be able use `&mut self` when
38	/// calling other contracts and not `&mut (impl TopLevelStorage +
39	/// BorrowMut<Self>)`. Should be fixed in the future by the Stylus team.
40	unsafe impl TopLevelStorage for BeaconProxy {}
41	
42	impl BeaconProxy {
43	    /// Initializes the proxy with `beacon`.
44	    ///
45	    /// If `data` is nonempty, it's used as data in a delegate call to the
46	    /// implementation returned by the beacon. This will typically be an
47	    /// encoded function call, and allows initializing the storage of the proxy
48	    /// like a Solidity constructor.
49	    ///
50	    /// # Arguments
51	    ///
52	    /// * `&mut self` - Write access to the contract's state.
53	    /// * `beacon` - The beacon address.
54	    /// * `data` - The data to pass to the beacon.
55	    ///
56	    /// # Errors
57	    ///
58	    /// * [`Error::InvalidBeacon`] - If the beacon is not a contract with the
59	    ///   interface [`IBeacon`][IBeacon].
60	    /// * [`Error::NonPayable`] - If the data is empty and
61	    ///   `self.vm().msg_value()` is not [`U256::ZERO`][U256].
62	    ///
63	    /// [IBeacon]: super::IBeacon
64	    /// [U256]: alloy_primitives::U256
65	    pub fn constructor(
66	        &mut self,
67	        beacon: Address,
68	        data: &Bytes,
69	    ) -> Result<(), Error> {
70	        Erc1967Utils::upgrade_beacon_to_and_call(self, beacon, data)?;
71	        self.beacon.set(beacon);
72	        Ok(())
73	    }
74	
75	    /// Returns the beacon.
76	    ///
77	    /// # Arguments
78	    ///
79	    /// * `&self` - Read access to the contract's state.
80	    #[must_use]
81	    pub fn get_beacon(&self) -> Address {
82	        self.beacon.get()
83	    }
84	}
85	
86	unsafe impl IProxy for BeaconProxy {
87	    fn implementation(&self) -> Result<Address, Vec<u8>> {
88	        Ok(IBeaconInterface::new(self.get_beacon())
89	            .implementation(self.vm(), Call::new())?)
90	    }
91	}
