249	    // `TestVM` answers every call with the return data of the last mock
250	    // registered, whichever call the mock is for. The proxy makes two calls to
251	    // serve a call to its fallback: it asks the beacon for the implementation
252	    // (`mock_beacon`), then delegates the call to it (`mock_implementation`).
253	    // So the tests register last the mock whose data they need: the one of the
254	    // implementation when they read the result of the call, and the one of the
255	    // beacon (that has to be decoded as an address) otherwise.
256	
257	    /// Makes `vm` see a contract at [`BEACON`], that answers `implementation()`
258	    /// the way [`Beacon`] does when running over the state of `beacon_vm`.
259	    fn mock_beacon(vm: &TestVM, beacon_vm: &TestVM) {
260	        deploy(vm, BEACON);
261	
262	        let calldata = function_selector!("implementation").to_vec();
263	        vm.mock_static_call(
264	            BEACON,
265	            calldata.clone(),
266	            execute::<Beacon>(beacon_vm, &calldata),
267	        );
268	    }
269	
270	    /// Mocks the delegate call of the proxy with `calldata` to [`ERC20`], with
271	    /// the outcome of running [`Erc20Example`] over the storage of the proxy.
272	    fn mock_implementation(vm: &TestVM, calldata: &[u8]) {
273	        vm.mock_delegate_call(
274	            ERC20,
275	            calldata.to_vec(),
276	            execute::<Erc20Example>(vm, calldata),
277	        );
278	    }
