38	/// An [`UpgradeableBeacon`] error.
39	#[derive(SolidityError, Debug)]
40	pub enum Error {
41	    /// Indicates an error related to the fact that the `implementation`
42	    /// of the beacon is invalid.
43	    InvalidImplementation(BeaconInvalidImplementation),
44	    /// The caller account is not authorized to perform an operation.
45	    UnauthorizedAccount(ownable::OwnableUnauthorizedAccount),
46	    /// Indicates an error related to the fact that the `owner` of the
47	    /// beacon is invalid.
48	    InvalidOwner(ownable::OwnableInvalidOwner),
49	}
