58	    fn from(err: ownable::Error) -> Self {
59	        match err {
60	            ownable::Error::UnauthorizedAccount(err) => {
61	                Error::UnauthorizedAccount(err)
62	            }
63	            ownable::Error::InvalidOwner(err) => Error::InvalidOwner(err),
64	        }
65	    }
