68	/// This contract is used in conjunction with one or more instances of
69	/// [`BeaconProxy`][BeaconProxy] to determine their implementation contract,
70	/// which is where they will delegate all function calls.
71	///
72	/// An owner is able to change the implementation the beacon points to, thus
73	/// upgrading the proxies that use this beacon.
74	///
75	/// [BeaconProxy]: super::BeaconProxy
76	#[public]
77	// The `#[public]` macro adds an undocumented helper method to the trait.
78	#[allow(missing_docs)]
79	pub trait IUpgradeableBeacon: IBeacon + IOwnable {
80	    /// Upgrades the beacon to a new implementation.
81	    ///
82	    /// # Arguments
83	    ///
84	    /// * `&mut self` - Write access to the contract's state.
85	    /// * `new_implementation` - The address of the new implementation.
86	    ///
87	    /// # Errors
88	    ///
89	    /// Implementing contracts should define their own error types for this
90	    /// function. Typically, errors may include:
91	    /// * The caller is not authorized to perform the upgrade.
92	    /// * The new implementation address is invalid (e.g., not a contract).
93	    /// * The upgrade operation failed for contract-specific reasons.
94	    ///
95	    /// The error should be encoded as a [`Vec<u8>`].
96	    fn upgrade_to(
97	        &mut self,
98	        new_implementation: Address,
99	    ) -> Result<(), Vec<u8>>;
100	}
101	
102	/// State of an [`UpgradeableBeacon`] contract.
103	#[storage]
104	pub struct UpgradeableBeacon {
105	    /// The address of the implementation contract.
106	    implementation: StorageAddress,
107	    /// The [`Ownable`] contract that owns the beacon.
108	    ownable: Ownable,
109	}
110	
111	unsafe impl TopLevelStorage for UpgradeableBeacon {}
112	
113	#[public]
114	#[implements(IBeacon, IOwnable)]
115	impl UpgradeableBeacon {
116	    /// Sets the address of the initial implementation, and the initial owner
117	    /// who can upgrade the beacon.
118	    ///
119	    /// # Arguments
120	    ///
121	    /// * `&mut self` - Write access to the contract's state.
122	    /// * `implementation` - The address of the initial implementation.
123	    ///
124	    /// # Errors
125	    ///
126	    /// * [`Error::InvalidImplementation`] - If `implementation` is not a
127	    ///   contract.
128	    /// * [`Error::UnauthorizedAccount`] - If the caller is not the owner.
129	    ///
130	    /// # Events
131	    ///
132	    /// * [`Upgraded`].
133	    #[constructor]
134	    pub fn constructor(
135	        &mut self,
136	        implementation: Address,
137	        initial_owner: Address,
138	    ) -> Result<(), Error> {
139	        self.ownable.constructor(initial_owner)?;
140	        self.set_implementation(implementation)?;
141	        Ok(())
142	    }
143	
144	    /// Upgrades the beacon to a new implementation.
145	    ///
146	    /// # Arguments
147	    ///
148	    /// * `&mut self` - Write access to the contract's state.
149	    /// * `new_implementation` - The address of the new implementation.
150	    ///
151	    /// # Errors
152	    ///
153	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
154	    ///   contract.
155	    /// * [`Error::UnauthorizedAccount`] - If the caller is not the owner.
156	    ///
157	    /// # Events
158	    ///
159	    /// * [`Upgraded`].
160	    pub fn upgrade_to(
161	        &mut self,
162	        new_implementation: Address,
163	    ) -> Result<(), Error> {
164	        self.ownable.only_owner()?;
165	        self.set_implementation(new_implementation)
166	    }
167	
168	    /// Upgrades the beacon to a new implementation.
169	    ///
170	    /// # Arguments
171	    ///
172	    /// * `&mut self` - Write access to the contract's state.
173	    /// * `new_implementation` - The address of the new implementation.
174	    ///
175	    /// # Errors
176	    ///
177	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
178	    ///   contract.
179	    ///
180	    /// # Events
181	    ///
182	    /// * [`Upgraded`].
183	    fn set_implementation(
184	        &mut self,
185	        new_implementation: Address,
186	    ) -> Result<(), Error> {
187	        if !AddressUtils::has_code(self, new_implementation) {
188	            return Err(Error::InvalidImplementation(
189	                BeaconInvalidImplementation {
190	                    implementation: new_implementation,
191	                },
192	            ));
193	        }
194	        self.implementation.set(new_implementation);
195	        self.vm().log(Upgraded { implementation: new_implementation });
196	        Ok(())
197	    }
198	}
199	
200	#[public]
201	impl IBeacon for UpgradeableBeacon {
202	    fn implementation(&self) -> Result<Address, Vec<u8>> {
203	        Ok(self.implementation.get())
204	    }
205	}
206	
207	#[public]
208	impl IOwnable for UpgradeableBeacon {
209	    fn owner(&self) -> Address {
210	        self.ownable.owner()
211	    }
212	
213	    fn transfer_ownership(
214	        &mut self,
215	        new_owner: Address,
216	    ) -> Result<(), Vec<u8>> {
217	        Ok(self.ownable.transfer_ownership(new_owner)?)
218	    }
219	
220	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>> {
221	        Ok(self.ownable.renounce_ownership()?)
222	    }
223	}
