232	            consume_attr::<attrs::Selector>(&mut node.attrs, "selector").map(|s| s.value.value());
233	        let fallback = consume_flag(&mut node.attrs, "fallback");
234	        let receive = consume_flag(&mut node.attrs, "receive");
235	        let constructor = consume_flag(&mut node.attrs, "constructor");
236	
237	        let kind = if fallback {
238	            // Fallback functions may have two signatures, either
239	            // with input calldata and output bytes, or no input and output.
240	            FnKind::Fallback {
241	                with_args: node.sig.inputs.len() > 1,
242	            }
243	        } else if receive {
244	            FnKind::Receive
245	        } else if constructor {
246	            FnKind::Constructor
247	        } else {
248	            FnKind::Function
249	        };
250	
251	        let num_specials = (fallback as i8) + (constructor as i8) + (receive as i8);
252	        if num_specials > 1 {
253	            emit_error!(
254	                node.span(),
255	                "function can be only one of fallback, receive or constructor"
256	            );
257	        }
258	        if num_specials > 0 && selector_override.is_some() {
259	            emit_error!(
260	                node.span(),
261	                "fallback, receive, and constructor can't have custom selector"
262	            );
263	        }
264	
265	        // name for generated rust, and solidity abi
266	        let name = node.sig.ident.clone();
267	        let (sol_name, name_err) = verify_sol_name(&kind, name.to_string(), selector_override);
268	        if let Some(err) = name_err {
269	            emit_error!(node.span(), err);
270	        }
271	        let sol_name = syn_solidity::SolIdent::new(&sol_name);
272	
273	        // determine state mutability
274	        let (inferred_purity, has_self) = Purity::infer(&node.sig);
275	        let purity = if payable || matches!(kind, FnKind::Receive) {
276	            Purity::Payable
277	        } else {
278	            inferred_purity
279	        };
280	
281	        let mut args = node.sig.inputs.iter();
282	        if inferred_purity > Purity::Pure {
283	            // skip self or storage argument
284	            args.next();
285	        }
286	        let inputs = match kind {
287	            FnKind::Function | FnKind::Constructor => args.map(PublicFnArg::from).collect(),
288	            _ => Vec::new(),
289	        };
290	        let input_span = node.sig.inputs.span();
291	
292	        let output = match &node.sig.output {
293	            syn::ReturnType::Default => None,
294	            syn::ReturnType::Type(_, ty) => Some(*ty.clone()),
295	        };
296	        let output_span = output
297	            .as_ref()
298	            .map(Spanned::span)
299	            .unwrap_or(node.sig.output.span());
300	
301	        let extension: E = E::default();
302	        Self {
303	            name,
304	            sol_name,
305	            purity,
306	            inferred_purity,
307	            kind,
308	
309	            has_self,
310	            inputs,
311	            input_span,
312	            output: node.sig.output.clone(),
313	            output_span,
314	
315	            extension,
316	        }
317	    }
318	}
