413	impl<E: FnArgExtension> From<&syn::FnArg> for PublicFnArg<E> {
414	    fn from(node: &syn::FnArg) -> Self {
415	        match node {
416	            syn::FnArg::Typed(pat_type) => match &*pat_type.pat {
417	                syn::Pat::Ident(pat_ident) => Self {
418	                    name: pat_ident.ident.clone(),
419	                    ty: *pat_type.ty.clone(),
420	                    extension: E::build(node),
421	                },
422	                other => {
423	                    emit_error!(other, "destructuring patterns are not supported in #[public] functions; use a named parameter instead");
424	                    // Dummy value so macro expansion can continue and report additional
425	                    // errors. The already-emitted error will prevent successful compilation.
426	                    Self {
427	                        name: syn::Ident::new("_", other.span()),
428	                        ty: parse_quote! { () },
429	                        extension: E::build(node),
430	                    }
431	                }
432	            },
433	            syn::FnArg::Receiver(recv) => {
434	                emit_error!(
435	                    recv,
436	                    "unexpected `self` parameter in #[public] function argument list"
437	                );
438	                // Dummy value (see comment above).
439	                Self {
440	                    name: syn::Ident::new("_", recv.span()),
441	                    ty: parse_quote! { () },
442	                    extension: E::build(node),
443	                }
444	            }
445	        }
446	    }
447	}
