449	/// Returns the Solidity name used for routing and an error string if the name doesn't match the
450	/// function kind.
451	fn verify_sol_name(
452	    kind: &FnKind,
453	    name: String,
454	    selector_override: Option<String>,
455	) -> (String, Option<String>) {
456	    let name = selector_override.unwrap_or(name.to_case(Case::Camel));
457	    let name_low = name.to_lowercase();
458	    let err_kind = if name_low == "receive" && !matches!(kind, FnKind::Receive) {
459	        Some("receive")
460	    } else if name_low == "fallback" && !matches!(kind, FnKind::Fallback { .. }) {
461	        Some("fallback")
462	    } else if (name_low == "constructor" || name_low == "stylus_constructor")
463	        && !matches!(kind, FnKind::Constructor)
464	    {
465	        Some("constructor")
466	    } else {
467	        None
468	    };
469	    let err = err_kind.map(|kind_name| {
470	        format!("{kind_name} function can only be defined using the corresponding attribute")
471	    });
472	    (name, err)
473	}
