21	/// Generate the code to call the special function (fallback, receive, or constructor) from the
22	/// public impl block. Emits an error if there are multiple implementations.
23	macro_rules! call_special {
24	    ($self:expr, $kind:pat, $kind_name:literal, $func:expr) => {{
25	        let specials: Vec<syn::Stmt> = $self
26	            .funcs
27	            .iter()
28	            .filter(|&func| matches!(func.kind, $kind))
29	            .map($func)
30	            .collect();
31	        if specials.is_empty() {
32	            None
33	        } else {
34	            if specials.len() > 1 {
35	                emit_error!(
36	                    concat!("multiple ", $kind_name),
37	                    concat!(
38	                        "contract can only have one #[",
39	                        $kind_name,
40	                        "] method defined"
41	                    )
42	                );
43	            }
44	            specials.first().cloned()
45	        }
46	    }};
47	}
