69	fn get_default_output(ty: &syn::Type) -> (TokenStream, TokenStream) {
70	    (
71	        quote! {
72	            Result<<<#ty as #AbiType>::SolType as #SolType>::RustType, stylus_sdk::stylus_core::calls::errors::Error>
73	        },
74	        quote! {
75	            Ok(<<#ty as #AbiType>::SolType as #SolType>::abi_decode_validate(&call_result)?)
