80	fn get_client_funcs<E: InterfaceExtension>(
81	    funcs: &[PublicFn<E::FnExt>],
82	    public: bool,
83	) -> (Vec<proc_macro2::TokenStream>, Vec<proc_macro2::TokenStream>) {
84	    let (client_funcs_definitions, client_funcs_declarations): (
85	            Vec<proc_macro2::TokenStream>,
86	            Vec<proc_macro2::TokenStream>,
87	        ) = funcs
88	        .iter()
89	        .map(|func| {
90	            let func_name = func.name.clone();
91	
92	            let (context, call) = func.purity.get_context_and_call();
93	
94	            let inputs = func.inputs.iter().map(|input| {
95	                let name = input.name.clone();
96	                let ty = input.ty.clone();
97	                quote! { #name: #ty }
98	            });
99	            let inputs_names = func.inputs.iter().map(|input| {
100	                input.name.clone()
101	            });
102	            let inputs_types = func.inputs.iter().map(|input| {
103	                let ty = input.ty.clone();
104	                quote! { #ty }
105	            });
106	
107	            let (output_type, output_decoding) = get_output_type_and_decoding(&func.output);
108	
109	            let function_selector = func.function_selector();
110	
111	            let funcs_visibility = if public { quote! { pub } } else { quote! {} };
112	
113	            let signature = quote! {
114	                #funcs_visibility fn #func_name(
115	                    &self,
116	                    host: &impl stylus_sdk::stylus_core::host::Host,
117	                    context: impl #context,
118	                    #(#inputs,)*
119	                ) -> #output_type
120	            };
121	
122	            let definition = quote! {
123	                #signature {
124	                    let inputs = <<(#(#inputs_types,)*) as #AbiType>::SolType as #SolType>::abi_encode_params(&(#(#inputs_names,)*));
125	                    use stylus_sdk::function_selector;
126	                    let mut calldata = Vec::from(#function_selector);
127	                    calldata.extend(inputs);
128	                    let call_result = #call(host, context, self.#STYLUS_CONTRACT_ADDRESS_FIELD, &calldata)?;
129	                    #output_decoding
130	                }
131	            };
132	            let declaration = quote! {
133	                #signature;
134	            };
135	            (definition, declaration)
136	        })
137	        .unzip();
138	    (client_funcs_definitions, client_funcs_declarations)
139	}
