141	fn get_output_type_and_decoding(output: &syn::ReturnType) -> (TokenStream, TokenStream) {
142	    match output {
143	        syn::ReturnType::Default => (
144	            quote! { Result<(), stylus_sdk::stylus_core::calls::errors::Error> },
145	            quote! { Ok(()) },
146	        ),
147	        syn::ReturnType::Type(_, ty) => {
148	            // Check if it's a path type (like Result<T, E> or ArbResult)
149	            let type_path = match ty.as_ref() {
150	                syn::Type::Path(type_path) => type_path,
151	                _ => return get_default_output(ty),
152	            };
153	
154	            // Check if the path is "Result" or "ArbResult"
155	            let segment = match type_path.path.segments.last() {
156	                Some(segment) => segment,
157	                None => {
158	                    emit_error!(ty.span(), "Expected a type path with segments, found none");
159	                    return get_default_output(ty);
160	                }
161	            };
162	            match segment.ident.to_string().as_str() {
163	                "ArbResult" => (
164	                    quote! {
165	                        stylus_sdk::ArbResult
166	                    },
167	                    quote! {
168	                        let decoded = <<Vec<u8> as #AbiType>::SolType as #SolType>::abi_decode_validate(&call_result);
169	                        match decoded {
170	                            Ok(decoded) => Ok(decoded),
171	                            Err(err) => Err("unable to decode to Vec<u8>".into()),
172	                        }
173	                    },
174	                ),
175	                "Result" => {
176	                    // Extract the generic arguments
177	                    let args = match &segment.arguments {
178	                        syn::PathArguments::AngleBracketed(args) => args,
179	                        _ => {
180	                            emit_error!(
181	                                ty.span(),
182	                                "Expected Result to have generic arguments, found none"
183	                            );
184	                            return get_default_output(ty);
185	                        }
186	                    };
187	
188	                    // Get the first generic argument (T in Result<T, E>)
189	                    if args.args.is_empty() {
190	                        emit_error!(
191	                            ty.span(),
192	                            "Expected Result to have at least one generic argument"
193	                        );
194	                        return get_default_output(ty);
195	                    }
196	                    if let syn::GenericArgument::Type(ok_type) = &args.args[0] {
197	                        get_default_output(ok_type)
198	                    } else {
199	                        emit_error!(
200	                            ty.span(),
201	                            "Expected Result to have a type as the first generic argument"
202	                        );
203	                        get_default_output(ty)
204	                    }
205	                }
206	                _ => get_default_output(ty),
207	            }
208	        }
209	    }
210	}
