213	    pub fn contract_client_gen(&self) -> proc_macro2::TokenStream {
214	        let (_, client_funcs_declarations) = get_client_funcs::<Extension>(&self.funcs, false);
215	
216	        let associated_types_declarations: Vec<proc_macro2::TokenStream> = self
217	            .associated_types
218	            .iter()
219	            .map(|(name, original_bounds)| {
220	                if original_bounds.is_empty() {
221	                    quote! { type #name: #AbiType; }
222	                } else {
223	                    quote! { type #name: #original_bounds + #AbiType; }
224	                }
225	            })
226	            .collect();
227	
228	        let ident = &self.ident;
229	
230	        let generic_params = if self.generic_params.is_empty() {
231	            quote! {}
232	        } else {
233	            let generic_params = &self.generic_params;
234	            quote! { <#generic_params> }
235	        };
236	
237	        let where_clause = if self.where_clause.is_empty() {
238	            quote! {}
239	        } else {
240	            let where_clause = &self.where_clause;
241	            quote! { where #where_clause }
242	        };
243	
244	        let output = quote! {
245	            #[cfg(feature = "contract-client-gen")]
246	            pub trait #ident #generic_params #where_clause {
247	                #(#associated_types_declarations)*
248	                #(#client_funcs_declarations)*
249	            }
250	        };
251	        output
252	    }
253	}
