316	/// Returns only `FnKind::Function` entries, excluding fallback, receive, and constructor.
317	fn regular_functions<E: FnExtension>(funcs: &[PublicFn<E>]) -> Vec<&PublicFn<E>> {
318	    funcs
319	        .iter()
320	        .filter(|f| matches!(f.kind, FnKind::Function))
321	        .collect()
322	}
