325	    pub fn impl_router(&self) -> syn::ItemImpl {
326	        let Self {
327	            self_ty,
328	            generic_params,
329	            where_clause,
330	            ..
331	        } = self;
332	        let functions = regular_functions(&self.funcs);
333	        let selector_consts = functions.iter().map(|f| f.selector_const());
334	        let selector_arms: Vec<_> = functions.iter().map(|f| f.selector_arm()).collect();
335	
336	        let fallback = call_special!(
337	            self,
338	            FnKind::Fallback { .. },
339	            "fallback",
340	            PublicFn::call_fallback
341	        );
342	        let fallback = fallback.unwrap_or_else(|| parse_quote!({ None }));
343	
344	        let receive = call_special!(self, FnKind::Receive, "receive", PublicFn::call_receive);
345	        let receive = receive.unwrap_or_else(|| parse_quote!({ None }));
346	
347	        let call_constructor = call_special!(
348	            self,
349	            FnKind::Constructor,
350	            "constructor",
351	            PublicFn::call_constructor
352	        );
353	        let constructor = call_constructor.unwrap_or_else(|| parse_quote!({ None }));
354	
355	        let implements_routes = self.implements_routes();
356	
357	        // Determine trait dynamic interface with associated types
358	        let iface = match &self.trait_ {
359	            Some(trait_) => {
360	                // If trait_ is something like foo::MyTrait<u32, u256>, trait_path_without_generics
361	                // will be foo::MyTrait
362	                let trait_path_without_generics = {
363	                    let mut path = trait_.clone();
364	                    if let Some(last_segment) = path.segments.last_mut() {
365	                        last_segment.arguments = syn::PathArguments::None;
366	                    }
367	                    path
368	                };
369	
370	                // Extract generic arguments from trait_ if present (e.g., "u32, u256" from the
371	                // previous example)
372	                let generic_args: Vec<proc_macro2::TokenStream> =
373	                    if let Some(last_segment) = trait_.segments.last() {
374	                        if let syn::PathArguments::AngleBracketed(args) = &last_segment.arguments {
375	                            args.args.iter().map(|arg| quote::quote! { #arg }).collect()
376	                        } else {
377	                            // No generic arguments
378	                            Vec::new()
379	                        }
380	                    } else {
381	                        Vec::new()
382	                    };
383	
384	                let associated_types: Vec<proc_macro2::TokenStream> = self
385	                    .associated_types
386	                    .iter()
387	                    .map(|(name, value)| quote::quote! { #name = #value })
388	                    .collect();
389	
390	                let combined_types = if !generic_args.is_empty() && !associated_types.is_empty() {
391	                    quote! { < #(#generic_args),* , #(#associated_types),* > }
392	                } else if !generic_args.is_empty() {
393	                    quote! { < #(#generic_args),* > }
394	                } else if !associated_types.is_empty() {
395	                    quote! { < #(#associated_types),* > }
396	                } else {
397	                    quote! {}
398	                };
399	
400	                &parse_quote! { dyn #trait_path_without_generics  #combined_types }
401	            }
402	            None => self_ty,
403	        };
404	
405	        parse_quote! {
406	            #[cfg(not(feature = "contract-client-gen"))]
407	            impl<S, #generic_params> #Router<S, #iface> for #self_ty
408	            where
409	                S: stylus_sdk::stylus_core::storage::TopLevelStorage + core::borrow::BorrowMut<Self> + stylus_sdk::stylus_core::ValueDenier + stylus_sdk::stylus_core::ConstructorGuard,
410	                #where_clause
411	            {
412	                type Storage = Self;
413	
414	                #[inline(always)]
415	                #[deny(unreachable_patterns)]
416	                fn route(storage: &mut S, selector: u32, input: &[u8]) -> Option<stylus_sdk::ArbResult> {
417	                    use stylus_sdk::function_selector;
418	                    use stylus_sdk::abi::{internal, internal::EncodableReturnType};
419	                    use alloc::vec;
420	
421	                    #(#selector_consts)*
422	                    match selector {
423	                        #(#selector_arms)*
424	                        _ => {
425	                            #(#implements_routes)*
426	                            None
427	                        }
428	                    }
429	                }
430	
431	                #[inline(always)]
432	                fn fallback(storage: &mut S, input: &[u8]) -> Option<stylus_sdk::ArbResult> {
433	                    #fallback
434	                }
435	
436	                #[inline(always)]
437	                fn receive(storage: &mut S) -> Option<Result<(), Vec<u8>>> {
438	                    #receive
439	                }
440	
441	                #[inline(always)]
442	                fn constructor(storage: &mut S, input: &[u8]) -> Option<stylus_sdk::ArbResult> {
443	                    #constructor
444	                }
445	            }
446	        }
447	    }
