61	/// A collection of utilities for working with [`Address`].
62	pub struct AddressUtils;
63	
64	impl AddressUtils {
65	    /// Performs a delegate call to `target` with the given `data`.
66	    ///
67	    /// # Arguments
68	    ///
69	    /// * `context` - Mutable access to the contract's state and to its host.
70	    /// * `target` - The address of the target contract.
71	    /// * `data` - The data to pass to the target contract.
72	    ///
73	    /// # Errors
74	    ///
75	    /// * [`Error::FailedCall`] - If the call to the target contract fails
76	    ///   without a revert reason.
77	    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
78	    ///   fails with a revert reason or if the call fails for any other reason.
79	    /// * [`Error::EmptyCode`] - If the target contract has no code.
80	    pub fn function_delegate_call(
81	        context: &mut (impl TopLevelStorage + HostAccess<Host = VM>),
82	        target: Address,
83	        data: &[u8],
84	    ) -> Result<Vec<u8>, Error> {
85	        // The call context borrows `context` mutably, so it must be built
86	        // before the host is accessed through `context.vm()`.
87	        let call = Call::new_mutating(context);
88	        let result =
89	            unsafe { call::delegate_call(context.vm(), call, target, data) };
90	        Self::verify_call_result_from_target(context, target, result)
91	    }
92	
93	    // TODO: Support more result types out of the box (e.g. `U256`, `U160`,
94	    // `String`, etc.).
95	    /// Helper function to verify that a low level call to smart-contract was
96	    /// successful.
97	    ///
98	    /// Reverts if the target was not a contract or if the call fails for any
99	    /// other reason. Bubbles up the revert reason (falling back to
100	    /// [`Error::FailedCall`]) in case of an unsuccessful call.
101	    ///
102	    /// # Arguments
103	    ///
104	    /// * `context` - Read access to the contract's host, used to look up the
105	    ///   code of `target`.
106	    /// * `target` - The address of the target contract.
107	    /// * `result` - The result of the call.
108	    ///
109	    /// # Errors
110	    ///
111	    /// * [`Error::EmptyCode`] - If the target contract has no code.
112	    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
113	    ///   fails with a revert reason or if the call fails for any other reason.
114	    /// * [`Error::FailedCall`] - If the call to the target contract fails
115	    ///   without a revert reason.
116	    pub fn verify_call_result_from_target<T: AsRef<[u8]>>(
117	        context: &impl HostAccess<Host = VM>,
118	        target: Address,
119	        result: Result<T, CallError>,
120	    ) -> Result<T, Error> {
121	        match result {
122	            Ok(returndata) => {
123	                if returndata.as_ref().is_empty()
124	                    && !Self::has_code(context, target)
125	                {
126	                    return Err(AddressEmptyCode { target }.into());
127	                }
128	                Ok(returndata)
129	            }
130	            Err(e) => Err(Self::revert(e)),
131	        }
132	    }
133	
134	    /// Returns `true` if there is code deployed at `account`, and `false`
135	    /// otherwise.
136	    ///
137	    /// # Arguments
138	    ///
139	    /// * `context` - Read access to the contract's host.
140	    /// * `account` - The address to look up the code of.
141	    pub(crate) fn has_code(
142	        context: &impl HostAccess<Host = VM>,
143	        account: Address,
144	    ) -> bool {
145	        context.vm().code_size(account) > 0
146	    }
147	}
148	
149	impl AddressUtils {
150	    /// Reverts with `error` if revert reason exists. Otherwise reverts with
151	    /// [`Error::FailedCall`].
152	    ///
153	    /// This behavior is aligned with Solidity implementation of
154	    /// [Address.sol].
155	    ///
156	    /// [Address.sol]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/utils/Address.sol
157	    fn revert(error: CallError) -> Error {
158	        match &error {
159	            CallError::Revert(data) if data.is_empty() => FailedCall {}.into(),
160	            _ => FailedCallWithReason { reason: error.encode().into() }.into(),
161	        }
162	    }
163	}
